Vector3 PhysicsBody::calculate_gravitational_acceleration(const PhysicsBody* A, double G) const {
    // We assume all positions/velocities are in the same frame
    const Vector3& diff = A->position - this->position;
    double r2 = diff.distance(diff); // diff.diff for self only, but here between two bodies
    double r = sqrt(r2);

